/* Adapt the design export to the interactive moderator and preview screens. */
[hidden] { display: none !important; }
:focus-visible { outline: 3px solid var(--c-blue); outline-offset: 4px; }

.admin-main h1, .breadcrumbs, .quiz-tile__title, .question-item__content, .preview-title {
  overflow-wrap: anywhere;
}
.quiz-list { grid-template-columns: repeat(auto-fill, minmax(min(280px, 100%), 1fr)); }
.quiz-list > li { min-width: 0; }
.quiz-tile { position: relative; height: 100%; margin: 0; }
.quiz-tile__title a { text-decoration: none; }
.quiz-tile__title a::after { content: ""; position: absolute; inset: 0; }
.quiz-tile__title, .panel-title { font-size: clamp(20px, 2.2vw, 28px); }

.question-item { grid-template-columns: auto minmax(0, 1fr) auto; }
.question-item__body { line-height: 1.35; letter-spacing: inherit; }
.question-item__options li { max-width: 100%; }
.question-item__options li.is-correct { color: var(--c-night); }
.question-item--inactive { opacity: 1; background: #f6f4ff; }
.question-item--inactive .question-item__content, .question-item--inactive .question-item__num { opacity: 0.65; }
.question-item__actions .checkbox { min-height: 32px; }

.option-fields { padding: 0; margin: 0 0 28px; border: 0; min-width: 0; }
.option-fields legend { padding: 0; margin-bottom: 6px; }
.option-fields .field-hint { margin-bottom: 20px; }
.option-row { grid-template-columns: minmax(0, 1fr) auto auto; }
.option-row__correct { text-transform: capitalize; }

.play--preview { min-height: calc(100dvh - 42px); }
.preview-title { text-align: right; }
.preview-actions { display: flex; margin-top: 20px; }
.preview-score { margin: 0; }
.play-option__letter { min-width: 36px; width: auto; min-height: 36px; height: auto; padding: 0 6px; }
.play-option__letter::before { content: attr(data-letter); }
.play-options.is-revealed .play-option.is-correct, .play-status--right { color: var(--c-night); }
.play-options.is-revealed .play-option.is-correct .play-option__letter { color: var(--c-night); }
.play-options.is-revealed button.play-option:disabled { box-shadow: none; transform: none; }
.play-status { margin-bottom: 16px; }

@media (max-width: 600px) {
  .admin-main { padding-top: 28px; }
  .card { padding: 16px; }
  .question-item { grid-template-columns: auto minmax(0, 1fr); gap: 12px; }
  .question-item__num { font-size: 24px; min-width: 1.2em; }
  .question-item__actions { grid-column: 1 / -1; flex-direction: row; align-items: center; flex-wrap: wrap; justify-content: space-between; }
  .option-row { gap: 8px; }
  .option-row .input { padding-inline: 8px; }
}
