/* Live game: a high-contrast projector view and thumb-sized phone controls. */
.live-stage { background: var(--c-night); color: var(--c-lavender); gap: clamp(24px, 5vh, 56px); }
.live-stage__tag { text-align: right; font-size: clamp(14px, 1.6vw, 22px); }
.live-stage .lobby__url { font-size: clamp(21px, 3.3vw, 58px); color: var(--c-sun); }
.live-stage .qr { justify-self: center; }
.live-stage .lobby { grid-template-columns: minmax(0, 1fr) auto; }
.live-stage .stage-option { flex-wrap: wrap; }
.live-stage .stage-option__title { min-width: min(35%, 6em); }
.live-correct { border-radius: 1000px; padding: 0.24em 0.65em; background: var(--c-night); color: var(--c-white); font-size: 0.65em; font-weight: 700; }
.live-greeting { font-weight: 800; overflow-wrap: anywhere; }
[data-live-game] .play-options { list-style: none; padding: 0; margin: 0; }
[data-live-game] .play-option { flex-wrap: wrap; min-height: 58px; }
[data-live-game] .play-option__title { min-width: min(32%, 5em); }
[data-live-game] .play-option__mark { color: inherit; }
[data-live-game] .play-status--wrong { background: #a81554; color: var(--c-white); }
[data-live-game] .waiting { justify-content: center; }
[data-live-game] .waiting .play-question__body { margin: 0; }
[data-live-game] .join-form .field { margin: 0; }
[data-live-game] .join-form label { text-align: center; }
.live-alert { padding: 12px 16px; border-radius: 12px; background: #ffe6ee; color: #85113e; }
.live-notice { padding: 0.5em 0.75em; margin: 12px 0 0; border-radius: 10px; background: var(--c-sun); color: var(--c-night); }
.live-stage .screen-controls__info { gap: 8px 24px; }

@media (max-width: 800px) {
  .live-stage .lobby { grid-template-columns: 1fr; }
  .live-stage .qr { width: min(70vw, 34vh, 420px); }
}

@media (prefers-reduced-motion: reduce) {
  [data-live-game] .waiting__gem { animation: none; }
}
EOF
