arguments.command:
cd /app && ruby <<'RUBY'
p = 'app/assets/javascripts/live_game.js'
s = File.read(p).sub('    const epoch = answerEpoch;', "    const epoch = answerEpoch;\n    const playerAtRequest = state.player;")
s.sub!('      if (data.version !== state.version || !(saving || epoch !== answerEpoch)) apply(data);', <<~JS.chomp.lines.map { |l| "      #{l}" }.join)
  if (!playerAtRequest && state.player && !data.player && data.phase !== "ended") {
    // This read left before the join response set the player's cookie.
    pollAgain = true;
  } else if (data.version !== state.version || !(saving || epoch !== answerEpoch)) {
    apply(data);
  }
JS
File.write(p, s)
RUBY
export PORT=3212 SECRET_KEY_BASE=$(bundle exec rails secret) QUIZZY_MODERATOR_USERNAME=moderator QUIZZY_MODERATOR_PASSWORD=live-smoke
bin/serve >tmp/live_verified_2.log 2>&1 & server=$!
trap 'kill "$server" 2>/dev/null || true' EXIT
for attempt in $(seq 1 60); do curl -fsS "http://127.0.0.1:$PORT/up" >/dev/null 2>&1 && break; sleep .2; done
for host in quizzy.test 127.0.0.1; do
  QUIZZY_TEST_URL="http://$host:$PORT" bundle exec ruby script/live_smoke_test || exit
 done
grep -aE 'Successfully upgraded|GameUpdatesChannel is streaming|ERROR|[0-9] (Internal|Forbidden)|Exception' tmp/live_verified_2.log | tail -25

